function Update-Interface([string]$GameDir) {
  try {
    $mpq = Join-Path $GameDir "Data\interface.MPQ"
    if (-not (Test-Path -LiteralPath $mpq)) { return }
    $old = [System.IO.File]::ReadAllBytes($mpq)
    $h = Get-Sha256 $old
    if ($h -eq $InterfaceFixed) { return }
    if ($h -ne $InterfaceOriginal -or $old.Length -ne $InterfaceOriginalSize) { return }
    $packed = New-Object System.IO.MemoryStream (,[System.Convert]::FromBase64String($InterfaceDelta))
    $inflate = New-Object System.IO.Compression.DeflateStream ($packed, [System.IO.Compression.CompressionMode]::Decompress)
    $plain = New-Object System.IO.MemoryStream
    $inflate.CopyTo($plain); $inflate.Dispose()
    $d = $plain.ToArray()
    $new = New-Object byte[] $InterfaceFixedSize
    $p = 0; $w = 0
    while ($p -lt $d.Length) {
        $t = $d[$p]; $p++
        if ($t -eq 67) {
            $src = [System.BitConverter]::ToInt32($d, $p); $n = [System.BitConverter]::ToInt32($d, $p + 4); $p += 8
            [System.Array]::Copy($old, $src, $new, $w, $n)
        } else {
            $n = [System.BitConverter]::ToInt32($d, $p); $p += 4
            [System.Array]::Copy($d, $p, $new, $w, $n); $p += $n
        }
        $w += $n
    }
    if ($w -ne $InterfaceFixedSize -or (Get-Sha256 $new) -ne $InterfaceFixed) {
        throw "the updated interface.MPQ does not match the expected result"
    }
    [System.IO.File]::WriteAllBytes($mpq, $new)
    Write-Host "interface.MPQ was updated: the login screen now has the account name and password fields." -ForegroundColor Green
  } catch {
    Write-Host "interface.MPQ was not changed: $($_.Exception.Message)" -ForegroundColor Red
  }
}

# Copies a file from the patch folder into the game folder if it is missing there.
function Copy-Included([string]$GameDir, [string]$Name, [string]$Sha) {
    $here = Join-Path $GameDir $Name
    $pack = Join-Path $PSScriptRoot $Name
    if (Test-Path -LiteralPath $here) { return $false }
    if (-not (Test-Path -LiteralPath $pack)) { return $false }
    if ($Sha -ne "" -and (Get-Sha256 ([System.IO.File]::ReadAllBytes($pack))) -ne $Sha) { return $false }
    Copy-Item -LiteralPath $pack -Destination $here
    return $true
}

function Install-Extras([string]$GameDir) {
    Update-Interface $GameDir

    if (Copy-Included $GameDir "gmod.dll" "34BFAF05CCA3395A6FC2C8D57C14ED428FA2C9FE9546FFB035884DE45A6C1FB2") {
        Write-Host "gmod.dll was missing - the included gmod.dll (by rajkosto) was copied"
        Write-Host "next to WoWClient.exe."
    }
    if (-not (Test-Path -LiteralPath (Join-Path $GameDir "D3D9.dll"))) {
        if (Copy-Included $GameDir "D3D9.dll" "B7401378B2B8E8C18C88A033E77C3EE99F4C7D2AC8CFCC949D79C1DD7FA99767") {
            [void](Copy-Included $GameDir "dgVoodoo.conf" "")
            Write-Host "dgVoodoo2 (by Dege) was copied next to WoWClient.exe for a smoother game"
            Write-Host "(D3D9.dll and dgVoodoo.conf). If the game runs worse, delete D3D9.dll."
        } else {
            Write-Host ""
            Write-Host "Tip: for a smoother game, also copy D3D9.dll and dgVoodoo.conf from"
            Write-Host "WoW053_ClientPatch.zip next to WoWClient.exe."
        }
    }

    if (-not (Test-Path -LiteralPath (Join-Path $GameDir "gmod.dll"))) {
        Write-Host ""
        Write-Host "WARNING: gmod.dll is missing next to WoWClient.exe." -ForegroundColor Yellow
        Write-Host "The game will not start without it. gmod.dll sends the account name and" -ForegroundColor Yellow
        Write-Host "password from the login screen to the server, so it is also needed to log in" -ForegroundColor Yellow
        Write-Host "to 0.5.3 servers." -ForegroundColor Yellow
        Write-Host "gmod.dll is included in WoW053_ClientPatch.zip: copy it next to" -ForegroundColor Yellow
        Write-Host "WoWClient.exe. It can also be found in The Alpha Project Discord:" -ForegroundColor Yellow
        Write-Host "https://discord.gg/RzBMAKU" -ForegroundColor Yellow
        Write-Host "To go back to your old WoWClient.exe, use WoWClient_before_patch.exe." -ForegroundColor Yellow
    }
}

try {
    if (-not (Test-Path -LiteralPath $Path)) {
        Write-Host "WoWClient.exe was not found: $Path" -ForegroundColor Red
        Write-Host "Put patch.bat and patch.ps1 in the game folder (next to WoWClient.exe)."
        exit 1
    }
    $Path = (Resolve-Path -LiteralPath $Path).Path
    $dir = Split-Path -Parent $Path
    $data = [System.IO.File]::ReadAllBytes($Path)
    $hash = Get-Sha256 $data
    Write-Host "File:   $Path"
    Write-Host "SHA256: $hash"

    if ($Results -contains $hash) {
        Write-Host "This WoWClient.exe is already patched." -ForegroundColor Green
        Install-Extras $dir
        exit 0
    }
    if (-not $Known.ContainsKey($hash)) {
        Write-Host "Unknown WoWClient.exe - nothing was changed." -ForegroundColor Red
        Write-Host "Please report the SHA256 above so support can be added."
        exit 1
    }
    $entry = $Known[$hash]
    Write-Host "Found:  $($entry.Name)"
    if ($data.Length -ne $entry.Size) { throw "unexpected file size" }

    if ($entry.Append -gt 0) {
        $extra = New-Object byte[] $entry.Append
        $tailBytes = Convert-Hex $Tails[$entry.Tail]
        [System.Array]::Copy($tailBytes, 0, $extra, 0, $tailBytes.Length)
        $grown = New-Object byte[] ($data.Length + $extra.Length)
        [System.Array]::Copy($data, 0, $grown, 0, $data.Length)
        [System.Array]::Copy($extra, 0, $grown, $data.Length, $extra.Length)
        $data = $grown
    }
    foreach ($p in $entry.Patches) {
        $offset = [int]$p[0]
        $bytes = Convert-Hex $p[1]
        [System.Array]::Copy($bytes, 0, $data, $offset, $bytes.Length)
    }
    $newHash = Get-Sha256 $data
    if ($newHash -ne $entry.Result) {
        throw "the patched file does not match the expected result ($newHash)"
    }

    $backup = Join-Path $dir "WoWClient_before_patch.exe"
    if (-not (Test-Path -LiteralPath $backup)) {
        Copy-Item -LiteralPath $Path -Destination $backup
        Write-Host "Backup: $backup"
    } else {
        Write-Host "Backup already exists, kept: $backup"
    }
    [System.IO.File]::WriteAllBytes($Path, $data)
    Write-Host "Done. WoWClient.exe is patched (SHA256 $newHash)." -ForegroundColor Green
    Install-Extras $dir
    exit 0
} catch {
    Write-Host "Patch failed, the original file was not changed: $($_.Exception.Message)" -ForegroundColor Red
    exit 1
}
